{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.fresh_mix_score AS WITH actual_alloc AS ( SELECT branch_code, order_date, category, style, meta1, meta2, meta3, alloc_option_count, alloc_mix_pct FROM snitch_db.maplemonk.fresh_tagged_allocation ), target_mix AS ( SELECT s.branch_code, s.order_date, s.category, s.style, s.meta1, s.meta2, s.meta3, s.sales_mix_blended_pct AS raw_sales_mix_target_pct, z.zone AS store_zone FROM snitch_db.maplemonk.fresh_sales_mix_reference s LEFT JOIN snitch_db.maplemonk.store_zone_map z ON s.branch_code = z.branch_code ), wh_mix AS ( SELECT order_date, scope AS wh_zone, category, style, meta1, meta2, meta3, warehouse_mix_pct AS raw_warehouse_mix_pct FROM snitch_db.maplemonk.warehouse_availability_mix ), joined_all AS ( SELECT COALESCE(a.branch_code, t.branch_code) AS branch_code, COALESCE(a.order_date, t.order_date) AS order_date, COALESCE(a.category, t.category, w.category) AS category, COALESCE(a.style, t.style, w.style) AS style, COALESCE(a.meta1, t.meta1, w.meta1) AS meta1, COALESCE(a.meta2, t.meta2, w.meta2) AS meta2, COALESCE(a.meta3, t.meta3, w.meta3) AS meta3, COALESCE(a.alloc_option_count, 0) AS alloc_option_count, COALESCE(a.alloc_mix_pct, 0) AS alloc_mix_pct, COALESCE(t.raw_sales_mix_target_pct, 0) AS raw_sales_mix_target_pct, COALESCE(w.raw_warehouse_mix_pct, 0) AS raw_warehouse_mix_pct, COALESCE(t.raw_sales_mix_target_pct, 0) AS capped_target_pct, CASE WHEN COALESCE(t.raw_sales_mix_target_pct, 0) >= 0.03 AND COALESCE(w.raw_warehouse_mix_pct, 0) = 0 THEN \'Yes\' ELSE \'No\' END AS warehouse_constrained_flag FROM actual_alloc a FULL OUTER JOIN target_mix t ON a.branch_code = t.branch_code AND a.order_date = t.order_date AND a.category = t.category AND a.style = t.style AND a.meta1 = t.meta1 AND a.meta2 = t.meta2 AND a.meta3 = t.meta3 LEFT JOIN wh_mix w ON w.order_date = COALESCE(a.order_date, t.order_date) AND w.wh_zone = COALESCE(t.store_zone, \'SOUTH\') AND w.category = COALESCE(a.category, t.category) AND w.style = COALESCE(a.style, t.style) AND w.meta1 = COALESCE(a.meta1, t.meta1) AND w.meta2 = COALESCE(a.meta2, t.meta2) AND w.meta3 = COALESCE(a.meta3, t.meta3) ), shipped_batches AS ( SELECT *, SUM(capped_target_pct) OVER (PARTITION BY branch_code, order_date) AS batch_target_sum FROM joined_all WHERE alloc_option_count > 0 ), target_normalized AS ( SELECT *, CASE WHEN batch_target_sum > 0 THEN capped_target_pct / batch_target_sum ELSE alloc_mix_pct END AS achievable_target_pct FROM shipped_batches ) SELECT branch_code, order_date, category, style, meta1, meta2, meta3, alloc_option_count, alloc_mix_pct, raw_sales_mix_target_pct, raw_warehouse_mix_pct, capped_target_pct, achievable_target_pct, warehouse_constrained_flag, ABS(alloc_mix_pct - achievable_target_pct) AS mix_deviation, GREATEST(achievable_target_pct, alloc_mix_pct) AS effective_weight FROM target_normalized;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            